import vertexai
from vertexai.preview.generative_models import GenerativeModel, Part
from vertexai.generative_models import HarmCategory, HarmProbability


def check_for_unsafe_content(document_text: str) -> dict:
    vertexai.init(project="YOUR_PROJECT_ID", location="YOUR_REGION")

    model = GenerativeModel("gemini-pro")

    response = model.generate_content(
        [Part.from_text(document_text)]
    )

    safety_feedback = []
    is_unsafe = False

    if response.prompt_feedback and response.prompt_feedback.safety_ratings:
        for rating in response.prompt_feedback.safety_ratings:
            safety_feedback.append({
                "category": rating.category.name,
                "probability": rating.probability.name
            })
            if rating.probability > HarmProbability.HARM_PROBABILITY_NEGLIGIBLE:
                is_unsafe = True

    # If the model blocked the content entirely, candidates will be empty
    if not response.candidates:
        is_unsafe = True

    return {
        "is_unsafe": is_unsafe,
        "safety_ratings": safety_feedback
    }

from dataclasses import dataclass, field
from typing import List, Dict, Any, Optional

@dataclass
class OCRRequest:
    document_content: str  # Base64 encoded image or document path
    document_type: Optional[str] = None # e.g., "image/jpeg", "application/pdf"

@dataclass
class LayoutBlock:
    id: str
    text_content: str
    bounding_box: List[float] # [x1, y1, x2, y2] normalized coordinates
    block_type: str # e.g., "paragraph", "line", "word", "table", "figure"
    confidence: Optional[float] = None

@dataclass
class TableCell:
    row_index: int
    column_index: int
    text_content: str
    bounding_box: List[float] # [x1, y1, x2, y2] normalized coordinates
    confidence: Optional[float] = None

@dataclass
class OCRResponse:
    extracted_text: str
    layout_blocks: List[LayoutBlock] = field(default_factory=list)
    tables: List[Dict[str, Any]] = field(default_factory=list) # List of tables, each a dict for flexibility
    raw_ocr_output: Optional[Dict[str, Any]] = None

@dataclass
class NormalizedDocument:
    normalized_text: str
    normalized_layout: List[LayoutBlock] = field(default_factory=list)
    normalized_tables: List[Dict[str, Any]] = field(default_factory=list)
    document_id: Optional[str] = None

